const D = { density:.5, energy:.55, hue:20, speed:1, scale:1, warp:.2, x:.5, y:.44, seed:0, style:'graphic', act:'cruise' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:v>b?b:v;
const sty = P.style, H = P.hue;
const hz = cl(P.y, .25, .72) * height;
const cx = cl(P.x, .12, .88) * width;
const groundH = Math.max(24, height - hz);
const yOf = t => hz + Math.pow(cl(t,0,1), 1.9) * groundH;
const hwOf = t => width * (.03 + t*1.05) * .5 * P.scale * (1 + P.warp*.55);
const NW = Math.round(6 + P.density*12);   // world depth rows visible
const NC = Math.round(4 + P.density*10);   // columns (fixed)

S.bass = (S.bass||0)*.8 + (A.bass||0)*.2;
S.tre  = (S.tre||0)*.8 + (A.treble||0)*.2;
const glow = (.4 + .6*P.energy) * (.5 + .55*K.intensity);
const kick = Math.min(1, K.pulse*(.5 + .5*K.intensity) + S.bass*.55);

// real-time depth scroll (integrates seconds — never re-phases)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt, 0, .1);
let sp = P.speed * (.55 + .9*K.intensity);
if (P.act === 'pulse') sp *= .4 + 1.4*kick;
if (P.act === 'tide')  sp *= .3 + 1.1*(.5 + .5*Math.sin(K.t*.05 + K.section*.9));
S.scroll = (S.scroll||0) + dt*sp*.55;
const scroll = S.scroll, frac = scroll - Math.floor(scroll), base = Math.floor(scroll);

// cached floor backdrop gradient
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+Math.round(P.y*20)+'|'+Math.round(P.scale*8)+'|'+Math.round(P.warp*10);
if (!S.base || S.key !== key) {
  const g = (S.base && S.base.width===width && S.base.height===height) ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR = 44;
  for (let i=0;i<STR;i++){ const f=i/STR, y=hz + f*groundH;
    let h,s,b;
    if (sty==='noir'){ h=0; s=0; b=6 + 10*f; }
    else if (sty==='op'){ h=0; s=0; b=10 + 8*f; }
    else if (sty==='halftone'){ h=H; s=10; b=8 + 12*f; }
    else { h=H; s=30-14*f; b=10 + 14*f; }   // graphic
    g.fill(h, cl(s,0,90), b, 100); g.rect(0, y, width, groundH/STR + 1);
  }
  S.base = g; S.key = key;
}
image(S.base, 0, 0);

// two tones per style (partial beat brighten — never a full-frame invert)
const bump = kick*.18*P.energy;
function tone(parity, near){
  let h,s,b;
  if (sty==='noir'){ h=0; s=0; b = parity ? cl(88 - 34*(1-near) + bump*40, 6, 98) : cl(10 + 8*near, 3, 40); }
  else if (sty==='op'){ h=0; s=0; b = parity ? cl(95 + bump*20, 6, 100) : 6; }
  else if (sty==='halftone'){ h=0; s=0; b = 5 + 8*near; }  // bg tone; dots drawn separately
  else { // graphic: two-tone hue pair
    if (parity){ h=H; s=cl(72 - 30*(1-near), 20, 92); b=cl(72 + 22*near + bump*45, 30, 100); }
    else { h=(H+180)%360; s=cl(60 - 26*(1-near), 15, 85); b=cl(26 + 20*near, 14, 70); }
  }
  return [h, cl(s,0,100), cl(b,2,100)];
}

// scrolling perspective checker — world rows physically travel toward viewer
noStroke();
for (let w=-1; w<=NW; w++){
  const t0=(w - frac)/NW, t1=(w+1 - frac)/NW;
  if (t1<=0 || t0>=1) continue;
  const tt0=cl(t0,0,1), tt1=cl(t1,0,1);
  const y0=yOf(tt0), y1=yOf(tt1), near=(tt0+tt1)/2;
  const wi = w + base;
  // op-art column warp phase travels with depth
  const warpAmt = (sty==='op') ? P.warp*0.5 : 0;
  for (let c=0;c<NC;c++){
    const parity = (wi + c) & 1;
    let u0=c/NC, u1=(c+1)/NC;
    if (warpAmt){ u0 += warpAmt*Math.sin(c*1.3 + wi*.9)/NC; u1 += warpAmt*Math.sin((c+1)*1.3 + wi*.9)/NC; }
    const hw0=hwOf(tt0), hw1=hwOf(tt1);
    const xa=cx-hw0+u0*2*hw0, xb=cx-hw0+u1*2*hw0;
    const xc=cx-hw1+u1*2*hw1, xd=cx-hw1+u0*2*hw1;
    if (sty==='halftone'){
      // dot-matrix: light parity -> big dot, dark -> small
      const mx=(xa+xb+xc+xd)/4, my=(y0+y1)/2;
      const cw=Math.min(Math.abs(xb-xa), Math.abs(y1-y0));
      const val = parity ? .92 : .18;
      fill(0,0, 4 + 90*val*(.6+.4*near), 100);
      ellipse(mx, my, cw*(.2+.7*val), cw*(.2+.7*val)*.7);
      continue;
    }
    const cc = tone(parity, near);
    fill(cc[0], cc[1], cc[2], 100);
    quad(xa,y0, xb,y0, xc,y1, xd,y1);
  }
}

// specular / rim shimmer sweep across the plane (continuous, additive, partial)
push(); blendMode(ADD); noStroke();
const bandY = hz + (( (K.t*.12*P.speed)%1 ) * groundH);
for (let i=0;i<3;i++){ const yy=bandY + i*groundH*.04;
  fill((sty==='graphic'?H:0), sty==='graphic'?40:0, 100, (4 + 6*glow)); rect(0, yy, width, groundH*.05); }
pop();

// horizon glow (partial, safe)
push(); blendMode(ADD); noStroke();
const flare=(kick*.5 + K.swell*.3)*glow;
for (let i=0;i<4;i++){ const rr=(4-i)*groundH*.045*(1+flare);
  fill((sty==='graphic'?H:(sty==='op'?0:H)), sty==='op'?0:40, 96, 3 + 7*flare); rect(0, hz-rr*.35, width, rr*.7); }
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
